(* [comment removed for export] *)
Definition hip_tail_exit (ra sp gp tp t0 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 vt1 vt2 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (D dn : Z) : machine_state -> Prop :=
  fun ms' => exists (a0' a1' a2' a3' a4' : word) (m' : mem),
    ms' = MS (mkR ra sp gp tp t0 vt1 vt2 s0 s1 a0' a1' a2' a3' a4' a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x12fa7c) fc None m' (seg_rom asegs)
    /\ munch [(D, D + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

Lemma hip_tail : forall (ra gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s8 s9 s10 t3 t5 t6 vt1 vt2 : word) F fc (m : mem) (FP L X0 X1 shift wpl D dn : Z),
  X0 = L -> X1 = L -> 1 <= shift <= 31 ->
  0 < D -> D mod 4 = 0 -> D + dn <= 2^47 -> L mod 4 = 0 -> D <= L -> L + 4 <= D + dn ->
  (D + dn <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < FP -> FP mod 16 = 0 -> FP + 304 <= 2^47 -> (D + dn <= FP \/ FP + 304 <= D) ->
  rw_cells asegs m (FP + 88) [C8 (Z_to_bv 64 (239136 + shift * 4)); C8 (Z_to_bv 64 (1 - wpl))] ->
  rw_cells asegs m (FP + 160) [C8 vt2] -> rw_cells asegs m (FP + 184) [C8 vt1] ->
  wr_at asegs m D dn -> acc asegs m D dn -> acc asegs m 239136 132 -> mem_inv asegs m ->
  evt asegs (hip_tail_exit ra (Z_to_bv 64 FP) gp tp t0 s0 s1 a5 a6 a7 s2 s3 s4 s5 s6 (Z_to_bv 64 shift) s8 s9 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 shift) t5 t6 vt1 vt2 F fc m D dn)
    (MS (mkR ra (Z_to_bv 64 FP) gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 X0) (Z_to_bv 64 X1) a2 a3 a4 a5 a6 a7
             s2 s3 s4 s5 s6 (Z_to_bv 64 shift) s8 s9 s10 (Z_to_bv 64 2147450880) t3 (Z_to_bv 64 shift) t5 t6)
        F (Z_to_bv 64 0x12fd30) fc None m (seg_rom asegs)).
Proof.
