(* [comment removed for export] *)
Definition hip_rows_exit (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (FP data pixh D dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' s0' s1' a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' t3' t4' t5' t6' : word) (j160 j184 j192 : list byte) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' s1' a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' t3' t4' t5' t6')
             F (Z_to_bv 64 0x12ffa0) fc None m' (seg_rom asegs)
    /\ munch [(FP + 160, FP + 200); (D, D + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (FP + 160) [CB 8 j160] /\ rw_cells asegs m' (FP + 168) [C8 (Z_to_bv 64 pixh); C8 (Z_to_bv 64 data)]
    /\ rw_cells asegs m' (FP + 184) [CB 8 j184] /\ rw_cells asegs m' (FP + 192) [CB 8 j192].

(* [comment removed for export] *)
Lemma hip_rows : forall (k : nat) (i : Z) (gp tp a0 a1 a2 a3 a4 a5 a6 a7 t5 : word) (j160 j184 j192 : list byte) F fc (m : mem) (FP data wpl pixh shift D dn : Z),
  Z.of_nat k = pixh - i -> 0 <= i -> (1 <= k)%nat -> pixh <= 20000 -> 1 <= wpl <= 626 -> 1 <= shift <= 31 ->
  0 < D -> D mod 4 = 0 -> D + dn <= 2^47 -> data mod 4 = 0 -> D <= data -> data + 4 * (wpl * pixh) <= D + dn ->
  (D + dn <= 0x7fff7000 \/ 0x10007fff8000 <= D) ->
  0 < FP -> FP mod 16 = 0 -> FP + 304 <= 2^47 -> (D + dn <= FP \/ FP + 304 <= D) -> 17594333495296 <= FP ->
  rw_cells asegs m (FP + 40) [C8 (Z_to_bv 64 (wpl * 4))] ->
  rw_cells asegs m (FP + 88) [C8 (Z_to_bv 64 (239136 + shift * 4)); C8 (Z_to_bv 64 (1 - wpl))] ->
  rw_cells asegs m (FP + 144) [C8 (Z_to_bv 64 (wpl * 4))] ->
  rw_cells asegs m (FP + 160) [CB 8 j160] -> rw_cells asegs m (FP + 168) [C8 (Z_to_bv 64 pixh); C8 (Z_to_bv 64 data)] ->
  rw_cells asegs m (FP + 184) [CB 8 j184] -> rw_cells asegs m (FP + 192) [CB 8 j192] ->
  wr_at asegs m D dn -> acc asegs m D dn -> acc asegs m 239136 132 -> mem_inv asegs m ->
  evt asegs (hip_rows_exit (Z_to_bv 64 FP) gp tp F fc m FP data pixh D dn)
    (MS (mkR (Z_to_bv 64 (data + 536870908 + 4 * (wpl * i))) (Z_to_bv 64 FP) gp tp
             (Z_to_bv 64 (data + 4 * (wpl * i))) (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -8)) (Z_to_bv 64 (data + 4 * (wpl * i)))
             (Z_to_bv 64 (wpl * 4)) (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -4))
             a0 a1 a2 a3 a4 a5 a6 a7
             (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -4)) (Z_to_bv 64 0) (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4)) (Z_to_bv 64 i)
             (Z_to_bv 64 (data + 536870908 + 4 * (wpl * i))) (Z_to_bv 64 shift)
             (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -4)) (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -4)) (Z_to_bv 64 (data + 4 * (wpl * i) + wpl * 4 + -8))
             (Z_to_bv 64 2147450880) (Z_to_bv 64 wpl) (Z_to_bv 64 shift) t5 (Z_to_bv 64 wpl))
        F (Z_to_bv 64 0x12fab8) fc None m (seg_rom asegs)).
